11	std::string make_temp_dir(const std::string& prefix) {
12	  std::error_code ec;
13	  const std::filesystem::path base = std::filesystem::temp_directory_path(ec);
14	  if (ec) return "";
15	  const std::string tmpl = (base / (prefix + "-XXXXXX")).string();
16	  std::vector<char> buf(tmpl.begin(), tmpl.end());
17	  buf.push_back('\0');
18	  const char* made = ::mkdtemp(buf.data());
19	  return made ? std::string(made) : std::string();
