194	// Fill one loop's LoopSyms from the ELF + the resolved source map. One
195	// symbolize() per endpoint (each call re-reads the ELF's symtab): the bare
196	// function name is the start symbol with its "+0xoff" stripped.
197	LoopSyms make_syms(const std::string& elf, uint64_t start, uint64_t end,
198	                   const std::map<uint64_t, std::string>& src_map) {
199	  LoopSyms s;
200	  const std::string raw_start = symbolize(elf, start);
201	  s.sym_start = sym_or_hex(raw_start, start);
202	  s.sym_end = sym_or_hex(symbolize(elf, end), end);
203	  s.fn_name = raw_start.substr(0, raw_start.find('+'));
204	  auto [fe, fx] = fn_range(elf, start);
205	  s.fn_entry = fe;
206	  s.fn_end = fx;
207	  if (auto it = src_map.find(start); it != src_map.end()) s.src_start = it->second;
208	  if (auto it = src_map.find(end); it != src_map.end()) s.src_end = it->second;
209	  auto [path, lineno] = parse_file_line(s.src_start);
210	  s.code_snippet = read_source_line(path, lineno);
211	  return s;
212	}
